namespace ValIO.Generators.Cpp.Runtime;

/// <summary>Emits the C++17 cancellation contract independently of HTTP and third-party headers.</summary>
internal static class CancellationRuntimeTemplates
{
    /// <summary>Emits shared ownership of cancellation state and the source that requests cancellation.</summary>
    /// <returns>The public cancellation header.</returns>
    public static string Header() => """
// Generated by ValIO — do not edit.
#pragma once
#include <memory>
#include <utility>

namespace ValIO {

namespace detail {
struct CancellationState;
class CancellationRegistration;
}

/// @brief Copyable cancellation signal retained safely by outstanding requests.
/// @details A default token never cancels. Cancellation requests do not imply that a server rolled back its work.
class CancellationToken {
public:
    /// @brief Creates a token that never requests cancellation.
    CancellationToken() noexcept = default;
    /// @brief Reports whether the associated source requested cancellation.
    /// @return True after the source has been cancelled; otherwise false.
    bool IsCancellationRequested() const noexcept;

private:
    /// @brief Retains the signal independently of the source object's lifetime.
    explicit CancellationToken(std::shared_ptr<detail::CancellationState> state) noexcept;
    std::shared_ptr<detail::CancellationState> _state;
    friend class CancellationSource;
    friend class detail::CancellationRegistration;
};

/// @brief Owns a thread-safe cancellation signal shared by any number of tokens.
/// @details Cancel interrupts an active HTTP socket and prevents queued dispatches. Connection establishment
/// follows the configured connection timeout. DNS resolution follows the operating system resolver's timeout;
/// cpp-httplib does not expose an interruptible resolver, so cancellation cannot promise an immediate return during DNS.
/// Copies refer to the same signal. Destroying a source does not cancel its tokens.
/// Plain HTTP I/O polls this signal. HTTPS cancellation uses cpp-httplib's public stop and progress hooks;
/// the final upstream SSLClient has no custom stream hook, so an active TLS read may wait for data or the configured
/// read timeout before returning. Immediate HTTPS cancellation is not guaranteed.
class CancellationSource {
public:
    /// @brief Creates a fresh signal that has not been cancelled.
    CancellationSource();
    /// @brief Returns a token retaining this signal.
    /// @return A copyable token suitable for synchronous calls or asynchronous captures.
    CancellationToken GetToken() const noexcept;
    /// @brief Requests cancellation once and synchronously notifies active socket subscriptions.
    /// @return True for the first cancellation request; false when cancellation was already requested.
    bool Cancel() const;

private:
    std::shared_ptr<detail::CancellationState> _state;
};

} // namespace ValIO
""";

    /// <summary>Emits lifetime-safe cancellation subscriptions inside the sole HTTP translation unit.</summary>
    /// <returns>The cancellation implementation fragment.</returns>
    public static string Source() => """
namespace detail {

struct CancellationCallback {
    std::mutex Mutex;
    bool Active = true;
    std::function<void()> Invoke;
};

struct CancellationState {
    std::atomic<bool> Cancelled{false};
    std::mutex Mutex;
    std::size_t NextId = 0;
    std::map<std::size_t, std::shared_ptr<CancellationCallback>> Callbacks;
};

class CancellationRegistration {
public:
    CancellationRegistration(const CancellationToken& token, std::function<void()> callback)
        : _state(token._state) {
        if (!_state) {
            return;
        }
        _callback = std::make_shared<CancellationCallback>();
        _callback->Invoke = std::move(callback);
        bool invokeImmediately;
        {
            const std::lock_guard<std::mutex> guard(_state->Mutex);
            invokeImmediately = _state->Cancelled.load(std::memory_order_acquire);
            if (!invokeImmediately) {
                _id = ++_state->NextId;
                _state->Callbacks.emplace(_id, _callback);
            }
        }
        if (invokeImmediately) {
            _callback->Invoke();
        }
    }

    ~CancellationRegistration() {
        if (!_callback) {
            return;
        }
        {
            const std::lock_guard<std::mutex> guard(_callback->Mutex);
            _callback->Active = false;
        }
        if (_state) {
            const std::lock_guard<std::mutex> guard(_state->Mutex);
            _state->Callbacks.erase(_id);
        }
    }

    CancellationRegistration(const CancellationRegistration&) = delete;
    CancellationRegistration& operator=(const CancellationRegistration&) = delete;

private:
    std::shared_ptr<CancellationState> _state;
    std::shared_ptr<CancellationCallback> _callback;
    std::size_t _id = 0;
};

} // namespace detail

bool CancellationToken::IsCancellationRequested() const noexcept {
    return _state && _state->Cancelled.load(std::memory_order_acquire);
}

CancellationToken::CancellationToken(std::shared_ptr<detail::CancellationState> state) noexcept : _state(std::move(state)) {}

CancellationSource::CancellationSource() : _state(std::make_shared<detail::CancellationState>()) {}

CancellationToken CancellationSource::GetToken() const noexcept {
    return CancellationToken(_state);
}

bool CancellationSource::Cancel() const {
    if (!_state) {
        return false;
    }
    if (_state->Cancelled.exchange(true, std::memory_order_acq_rel)) {
        return false;
    }
    std::vector<std::shared_ptr<detail::CancellationCallback>> callbacks;
    {
        const std::lock_guard<std::mutex> guard(_state->Mutex);
        for (const auto& entry : _state->Callbacks) {
            callbacks.push_back(entry.second);
        }
    }
    for (const auto& callback : callbacks) {
        const std::lock_guard<std::mutex> guard(callback->Mutex);
        if (callback->Active) {
            callback->Invoke();
        }
    }
    return true;
}
""";
}
